package thaumcraft.test;
import java.util.*;
import com.mojang.authlib.GameProfile;
import net.minecraft.core.*;
import net.minecraft.server.level.*;
import net.minecraft.network.chat.Component;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.event.server.ServerStartedEvent;
import net.minecraftforge.event.entity.player.PlayerInteractEvent;
import net.minecraftforge.eventbus.api.listener.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
import thaumcraft.*;
import thaumcraft.golems.*;
import static thaumcraft.test.ThaumaturgyProbe.*;
@Mod.EventBusSubscriber(modid=Thaumcraft.MODID)
public final class TaskProbe {
 public static final BlockPos Q=new BlockPos(360,205,8);static int ticks;static boolean done,denyUse,denyBreak;static ServerPlayer p;
 @SubscribeEvent public static void deny(PlayerInteractEvent.RightClickBlock e){if(System.getProperty("thaumcraft.thaumaturgyProbe","").startsWith("tasks-")&&denyUse){e.setUseBlock(net.minecraftforge.common.util.Result.DENY);e.setUseItem(net.minecraftforge.common.util.Result.DENY);}}
 @SubscribeEvent public static void deny(net.minecraftforge.event.level.BlockEvent.BreakEvent e){if(System.getProperty("thaumcraft.thaumaturgyProbe","").startsWith("tasks-")&&denyBreak)e.setResult(net.minecraftforge.common.util.Result.DENY);}
 static WorkerGolem worker(ServerPlayer p,BlockPos at){var g=new WorkerGolem(GolemContent.GOLEM.get(),p.level());g.configure(p,new GolemDesign(3,1,1,0),at,0);return g;}
 static net.minecraft.world.entity.animal.cow.Cow cow(ServerPlayer p,BlockPos q,boolean baby){var a=new net.minecraft.world.entity.animal.cow.Cow(net.minecraft.world.entity.EntityTypes.COW,p.level());a.setPos(net.minecraft.world.phys.Vec3.atBottomCenterOf(q));a.setNoAi(true);if(baby)a.setAge(-24000);p.level().addFreshEntity(a);return a;}
 public static void rules(ServerPlayer p){var l=p.level();for(var animal:l.getEntitiesOfClass(net.minecraft.world.entity.animal.Animal.class,new net.minecraft.world.phys.AABB(Q).inflate(20)))animal.discard();for(int x=21;x<=23;x++)l.setChunkForced(x,0,true);for(var q:BlockPos.betweenClosed(Q.offset(-8,0,-5),Q.offset(12,8,5)))l.setBlockAndUpdate(q,Blocks.AIR.defaultBlockState());for(var q:BlockPos.betweenClosed(Q.offset(-6,-1,-5),Q.offset(12,-1,5)))l.setBlockAndUpdate(q,Blocks.STONE.defaultBlockState());
  var s=GolemProbe.seal(p,SealKind.USE,Q.east(2));l.setBlockAndUpdate(s.getBlockPos(),s.getBlockState().setValue(SealBlock.FACING,Direction.WEST));l.setBlockAndUpdate(s.support(),Blocks.LEVER.defaultBlockState());s.useEmpty=true;var g=worker(p,Q.east());p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.GOLD_INGOT,11));check(GolemInteraction.click(l,p,g,s)&&l.getBlockState(s.support()).getValue(BlockStateProperties.POWERED),"Empty-hand native lever click failed");check(p.getMainHandItem().getCount()==11&&g.cargo.isEmpty(),"Use changed owner's hand");denyUse=true;check(!GolemInteraction.click(l,p,g,s)&&l.getBlockState(s.support()).getValue(BlockStateProperties.POWERED),"Use bypasses denied interaction");denyUse=false;
  l.setBlockAndUpdate(s.support(),Blocks.DIRT.defaultBlockState());s.useEmpty=false;g.cargo.setItem(0,new ItemStack(Items.DIAMOND_HOE));boolean tilled=GolemInteraction.click(l,p,g,s);check(tilled&&l.getBlockState(s.support()).is(Blocks.FARMLAND)&&g.cargo.getItem(0).getDamageValue()==1,"Use hoe: result="+tilled+" state="+l.getBlockState(s.support())+" cargo="+g.cargo.getItem(0)+" damage="+g.cargo.getItem(0).getDamageValue()+" above="+l.getBlockState(s.support().above()));
  l.setBlockAndUpdate(s.support(),Blocks.OAK_LOG.defaultBlockState());g.cargo.setItem(0,new ItemStack(Items.DIAMOND_AXE));s.useLeft=true;denyBreak=true;check(!GolemInteraction.click(l,p,g,s)&&l.getBlockState(s.support()).is(Blocks.OAK_LOG)&&g.cargo.getItem(0).getDamageValue()==0,"Left click bypassed protected break");denyBreak=false;check(GolemInteraction.click(l,p,g,s)&&l.isEmptyBlock(s.support())&&g.cargo.getItem(0).getDamageValue()==1,"Native left break did not damage/return tool");
  l.setBlockAndUpdate(s.support(),Blocks.STONE.defaultBlockState());s.useLeft=false;s.useAir=true;g.setPos(net.minecraft.world.phys.Vec3.atBottomCenterOf(Q));g.cargo.setItem(0,new ItemStack(Items.DIRT,3));check(GolemInteraction.click(l,p,g,s)&&l.getBlockState(s.useTarget()).is(Blocks.DIRT)&&g.cargo.getItem(0).getCount()==2,"Air mode placed sample or failed physical payment");l.removeBlock(s.useTarget(),false);
  s.useAir=false;g.setPos(net.minecraft.world.phys.Vec3.atBottomCenterOf(Q.east()));l.setBlockAndUpdate(s.support(),Blocks.CAULDRON.defaultBlockState());g.cargo.setItem(0,new ItemStack(Items.WATER_BUCKET));check(GolemInteraction.click(l,p,g,s)&&l.getBlockState(s.support()).is(Blocks.WATER_CAULDRON)&&g.cargo.getItem(0).is(Items.BUCKET),"Use destroyed bucket remainder");
  var timber=GolemProbe.seal(p,SealKind.LUMBER,Q.west(3));for(int i=0;i<4;i++)l.setBlockAndUpdate(Q.west(4).above(i),Blocks.OAK_LOG.defaultBlockState());l.setBlockAndUpdate(Q.west(7).above(4),Blocks.OAK_LOG.defaultBlockState());check(GolemTasks.furthest(l,timber,Q.west(4)).equals(Q.west(4).above(3)),"Connected timber traversal escaped tree");
  var butcher=GolemProbe.seal(p,SealKind.BUTCHER,Q.east(9));var a=cow(p,Q.east(8),false);var b=cow(p,Q.east(9).north(),false);var baby=cow(p,Q.east(10),true);check(!GolemTasks.butcher(l,butcher,p,a)&&!GolemTasks.butcher(l,butcher,p,baby),"Butcher counts babies toward breeding pair");var c=cow(p,Q.east(10).north(),false);check(GolemTasks.butcher(l,butcher,p,a),"Butcher ignored adult surplus: query="+l.getEntitiesOfClass(net.minecraft.world.entity.animal.Animal.class,GolemTasks.area(butcher)).size()+" adult="+GolemTasks.adult(a)+" position="+a.position()+" area="+GolemTasks.area(butcher));c.discard();check(!GolemTasks.butcher(l,butcher,p,a),"Butcher did not revalidate remaining adults");a.discard();b.discard();baby.discard();
  s.useLeft=true;s.useAir=true;s.useEmpty=true;s.useSneak=true;s.useProvision=true;s.sample(0,new ItemStack(Items.DIRT));s.exact=false;s.setChanged();p.setPos(s.getBlockPos().getX()+.5,s.getBlockPos().getY(),s.getBlockPos().getZ()+2);var menu=new SealMenu(107,p.getInventory(),s);check(menu.value(21)==1&&menu.value(25)==1&&menu.clickMenuButton(p,15)&&!s.useSneak,"Use options did not synchronize/edit");s.useSneak=true;s.setChanged();
  Thaumcraft.LOGGER.info("TASK_RULES_OK: native clicks, denied use/break, tool durability, air placement/payment, bucket return, bounded tree, adult recount and options");
 }
 @SubscribeEvent public static void start(ServerStartedEvent e){String mode=System.getProperty("thaumcraft.thaumaturgyProbe","");if(!mode.equals("tasks-write")&&!mode.equals("tasks-read"))return;var l=e.getServer().overworld();for(int x=21;x<=23;x++)l.setChunkForced(x,0,true);l.setChunkForced(12,0,true);l.setChunkForced(11,0,true);p=new ServerPlayer(e.getServer(),l,new GameProfile(UUID.fromString("6be7c45a-6764-4c37-b8d3-d719a6fdc022"),"TaskProbe"),ClientInformation.createDefault()){@Override public void sendSystemMessage(Component c,boolean o){}@Override protected ItemCooldowns createItemCooldowns(){return new ItemCooldowns();}};knowledge(p);p.setPos(Q.getX()+.5,Q.getY(),Q.getZ()+.5);if(mode.equals("tasks-read")){var s=(SealEntity)l.getBlockEntity(Q.east(2));check(s!=null&&s.kind()==SealKind.USE&&s.useLeft&&s.useAir&&s.useEmpty&&s.useSneak&&s.useProvision&&!s.exact&&s.filter.is(Items.DIRT),"Use options lost at restart");}}
 @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){String mode=System.getProperty("thaumcraft.thaumaturgyProbe","");if(!mode.equals("tasks-write")&&!mode.equals("tasks-read")||done||++ticks<40)return;if(mode.equals("tasks-write"))rules(p);else{var legacy=(SealEntity)e.server().overworld().getBlockEntity(GolemProbe.Q.west(5));check(legacy!=null&&legacy.kind()==SealKind.STOCK&&legacy.sample(8).is(Items.EMERALD)&&legacy.amounts[8]==11,"port.21 Stock migration lost filters/quantities");check(e.server().overworld().getEntitiesOfClass(WorkerGolem.class,new net.minecraft.world.phys.AABB(GolemProbe.Q).inflate(16)).stream().anyMatch(g->g.hasCustomName()&&g.getCustomName().getString().equals("Persistent delivery")&&GolemProbe.Q.west(5).equals(g.delivery())&&g.cargo.getItem(0).getCount()==16),"port.21 physical Stock route lost at update");Thaumcraft.LOGGER.info("TASK_PORT21_OK: saved Stock filters and pre-existing physical delivery preserved");}done=true;Thaumcraft.LOGGER.info(mode.equals("tasks-write")?"TASK_WRITE_OK":"TASK_RESTART_OK");e.server().halt(false);}
}
